def transform(grid):
    counts = Counter(v for row in grid for v in row)
    # The more frequent of the two colors becomes the less frequent color;
    # the less frequent color maps to zero.
    colors = list(counts)
    if len(colors) != 2:
        raise ValueError('expected a two-color grid')
    a, b = colors
    rare, common = (a, b) if counts[a] < counts[b] else (b, a)
    return [[rare if v == common else 0 for v in row] for row in grid]
",
